  (* LPS 727298f3: the launch's reserved intervals at the main entry ([AllocRepX.akernel_resx]),
     from the ledger's shape, the mmap base and the mappings' apartness ([ak_reserved], that is
     [AsanPlanSound.co_res]) and [alloc_top = hceil] ([ak_top], [Hceil]). *)
  Lemma akernel_resx_main : akernel_resx model.
  Proof.
    destruct ak_reserved as [kb (Hr & Hmb & Hd & _)].
    apply (@akernel_resx_intro HCEIL model kb Hr Hmb).
    - rewrite ak_top. symmetry. exact Hceil.
    - intros iv Hiv e He. exact (proj1 (Forall_forall _ _) (proj1 (Forall_forall _ _) Hd iv Hiv) e He).
  Qed.

  Theorem akernel_main : ltac2:(zQ "60!h9!jc!jle!npa!o8!oe@3$3?5HCEIL@6$2@2$1@1$0#k0?3sp0@2$1@1$0#k0?4brk0@2$4@1$5?1h?1E?3env?2ts?3AL0?5model").
Proof.
  (* LPS 727298f3: [akernel] is [akernel_pre /\ akernel_resx]; the recorded proof builds the first
     half (its result type is [akernel_pre_d]), [akernel_resx_main] the second.  [akernel_pre]'s
     first conjunct is over [segments_reserved asegs] (the image's reservations, [ak1]); the
     record was decoded, the list in that one conjunct set from [vm_reserved (m_vmmaps model)] to
     [segments_reserved asegs], and the record compressed again; decoded, the two terms differ
     there only, and [vm_reserved] stays in the conjuncts that read the ledger. *)
  unfold akernel. split; [| exact akernel_resx_main].
